import {allCardInstanceIds,createGame,gameStats,transition,type GameCommand,type GameState} from '@madou/engine';
import {getAction} from '@madou/catalog';
import {assignCharacter,entropy,takeCard,trimHand} from './scenario-tools.js';
/** Real dedicated earth spear removes C/D, then real intervening turns and CHANT prepare the final two-person destruction. */
export function makeR6ExtinctionScenario(players:{id:string;name:string}[]):GameState{
 let s=createGame(players,entropy(),{startingSeat:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];assignCharacter(s,a,'小人のランバ');assignCharacter(s,b,'魔聖母ディア');assignCharacter(s,c,'忍びのイダ');assignCharacter(s,d,'黒妖精のアーネス');for(const p of Object.values(s.players))p.permanent={warrior_level:20,magic_level:20,spirit:20};s.players[a]!.damage=gameStats(s,a).endurance-8;for(const id of [c,d])s.players[id]!.damage=gameStats(s,id).endurance-3;
 const earth=takeCard(s,a,'a2-p16-r2c3'),destruction=takeCard(s,a,'a2-p13-r2c3');trimHand(s,a,earth,destruction);s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];
 function act(actorId:string,command:GameCommand){const input={actorId,command},e=entropy(),r=transition(s,input,e);if(!r.ok)throw Error(`S27_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('S27_FIXTURE_REPLAY');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('S27_FIXTURE_CARDS');}
 function finish(){for(let n=0;n<300;n++){const w=s.windows?.at(-1);if(!w)return;act(w.participants[w.cursor]!,{type:'PASS'});}throw Error('S27_FIXTURE_WINDOW');}
 function nextOwn(){for(let n=0;n<40;n++){const actor=s.seatOrder[s.turnSeat]!;if(s.phase==='turn-start'&&actor===a){act(a,{type:'START_TURN'});act(a,{type:'CHOOSE_DRAW',draw:false});return;}if(s.phase==='turn-start')act(actor,{type:'START_TURN'});else if(s.phase==='draw')act(actor,{type:'CHOOSE_DRAW',draw:false});else if(s.phase==='action')act(actor,{type:'PASS_ACTION'});else if(s.phase==='withdrawal')act(actor,{type:'PASS_WITHDRAWAL'});else if(s.phase==='hand-adjustment'){act(actor,{type:'END_TURN',discardIds:s.players[actor]!.hand.filter(id=>id!==destruction).slice(0,Math.max(0,s.players[actor]!.hand.length-gameStats(s,actor).handLimit))});finish();}else throw Error('S27_FIXTURE_TURN');}throw Error('S27_FIXTURE_TURN_LIMIT');}
 for(const p of players)act(p.id,{type:'PASS_SETUP'});act(a,{type:'START_TURN'});act(a,{type:'CHOOSE_DRAW',draw:false});act(a,{type:'ATTACK',cardInstanceId:earth,targetIds:[c,d],dedicated:true});finish();if(s.players[c]!.presence!=='dead'||s.players[d]!.presence!=='dead'||s.outcome)throw Error('S27_FIXTURE_DEATHS');nextOwn();act(a,{type:'CHANT',cardInstanceId:destruction});nextOwn();return s;
}
